/// Bully (Uncommon, 0 energy, Enemy). Faithful to C# `Bully`: damage =
/// `CalculationBase(4) + ExtraDamage(2) * target.Vulnerable`. Bead
/// `sts2-rs-0yt1b` (was wrongly doubling on Minion). `ExtraDamage` is the
/// per-Vulnerable-stack multiplier coefficient (2 base; OnUpgrade → 3, not
/// modeled at this pin since spec upgrade-deltas aren't surfaced).
/// `CalculatedDamage`: base + ExtraDamage per Vulnerable **on the target**.
///
/// Bead `sts2-rs-4lx7y`: C# `Bully.cs` `ExtraDamageVar(2)` with
/// `OnUpgrade UpgradeValueBy(1m)` → +2 per Vulnerable / +3 upgraded.
///
/// One of the four target-reading previews: with `target: None` the multiplier
/// is zero and the face shows the plain base, which is exactly what the game
/// shows before the player hovers an enemy.
pub(crate) fn preview_bully(state: &CombatState, card: &Card, target: Option<CreatureUid>) -> i32 {
    let extra = if card.upgraded { 3 } else { 2 };
    let vuln = target.map_or(0, |t| enemy_vulnerable(state, t));
    card.base_damage + extra * vuln
}

pub(crate) fn play_bully(state: &mut CombatState, target: Option<CreatureUid>) -> EffectResult {
    let t = target.expect("Bully: Enemy-targeted");
    let dmg = resolving_preview(state, preview_bully, target);
    let _ = deal_damage_player_to_enemy(state, t, dmg);
    EffectResult::Resolved
}

